package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.util.*;
/** Separate test UID and synthetic queue only. Never connects to a glass or provider. */
public final class BatchQueueChecks {
 static int count;static void ok(boolean b,String m){count++;if(!b)throw new AssertionError(m);}interface Work{void run()throws Exception;}
 static void rejects(Work w)throws Exception{boolean rejected=false;try{w.run();}catch(java.io.IOException|IllegalArgumentException e){rejected=true;}ok(rejected,"invalid/stale selection rejected");}
 static void seed(Context c,String[] keys)throws Exception{JSONArray ledger=new JSONArray(),held=new JSONArray();ArrayList<String> queue=new ArrayList<>();for(int i=0;i<keys.length;i++){ledger.put(new JSONObject().put("key",keys[i]).put("message","synthetic question "+i).put("referenceKey","").put("tracked",true).put("requestState","QUEUED").put("time",100));held.put(keys[i]);queue.add(TrackedWebRequest.wire(keys[i],"synthetic question "+i));}ok(c.getSharedPreferences("loki_web_console",0).edit().putString("outbox",ledger.toString()).commit(),"seed ledger");ok(MainActivity.persistReviewCommands(c,queue),"seed queue");ok(ReconnectReview.prefs(c).edit().clear().putString("held",held.toString()).commit(),"seed held");}
 public static int run(Context c)throws Exception{count=0;String[] keys={"1".repeat(64),"2".repeat(64),"3".repeat(64)};seed(c,keys);String queue=MainActivity.pendingReviewCommands(c).toString(),ledger=ConversationContinuation.ledger(c).toString();long revision=CommandNotice.revision();JSONObject result=ReconnectReview.approveBatch(c,new JSONArray().put(keys[0]).put(keys[1]));ok(result.getInt("selected")==2&&result.getInt("resumed")==2&&result.getInt("newRequests")==0,"two original requests resumed, no duplicate");ok(!ReconnectReview.held(c,keys[0])&&!ReconnectReview.held(c,keys[1])&&ReconnectReview.held(c,keys[2]),"unselected request remains held");ok(MainActivity.pendingReviewCommands(c).toString().equals(queue),"original queue/order preserved");ok(ConversationContinuation.ledger(c).toString().equals(ledger),"original ledger/messages preserved");ok(CommandNotice.revision()>revision,"dispatcher awakened");ok(ReconnectReview.dispatchIndex(c,MainActivity.pendingReviewCommands(c))==0,"eligible queue head available");ok(ReconnectReview.approveBatch(c,new JSONArray().put(keys[0]).put(keys[1])).getInt("resumed")==0,"repeat does not create/release new requests");
  String held=ReconnectReview.prefs(c).getString("held","");rejects(()->ReconnectReview.approveBatch(c,new JSONArray().put(keys[2]).put("4".repeat(64))));ok(held.equals(ReconnectReview.prefs(c).getString("held","")),"stale batch has no partial approval");rejects(()->ReconnectReview.approveBatch(c,new JSONArray().put(keys[2]).put(keys[2])));rejects(()->ReconnectReview.approveBatch(c,new JSONArray()));
  JSONArray changed=ConversationContinuation.ledger(c);changed.getJSONObject(2).put("requestState","RUNNING");c.getSharedPreferences("loki_web_console",0).edit().putString("outbox",changed.toString()).commit();rejects(()->ReconnectReview.approveBatch(c,new JSONArray().put(keys[2])));ok(ReconnectReview.held(c,keys[2]),"running request is not replayed");
  seed(c,keys);revision=CommandNotice.revision();JSONObject merged=ConversationContinuation.merge(c,new JSONObject().put("keys",new JSONArray().put(keys[0]).put(keys[1])).put("changeId","synthetic-merge-operation").put("message","two synthetic questions together"));ok(merged.getBoolean("queued"),"merge queued");ok(MainActivity.pendingReviewCommands(c).size()==2,"merge reduces exactly two to one");ok(CommandNotice.revision()>revision,"merged dispatcher awakened");JSONArray rows=ConversationContinuation.ledger(c);ok(rows.length()==4&&rows.getJSONObject(0).getString("requestState").equals("SUPERSEDED")&&rows.getJSONObject(1).getString("requestState").equals("SUPERSEDED"),"originals retained as superseded");ok(rows.getJSONObject(3).getString("message").equals("two synthetic questions together"),"merged text is retained");JSONObject again=ConversationContinuation.merge(c,new JSONObject().put("keys",new JSONArray().put(keys[0]).put(keys[1])).put("changeId","synthetic-merge-operation").put("message","two synthetic questions together"));ok(again.optBoolean("duplicate")&&MainActivity.pendingReviewCommands(c).size()==2,"merge retry idempotent");return count;
 }
}
